def calculate_exp(gold, exp_rate=1.5):
    return gold * exp_rate

def check_level(exp):
    if exp >= 100:
        return "Level up!"
    elif exp >= 50:
        return "Close to leveling!"
    else:
        return "Keep grinding!"

exp = calculate_exp(80)
result = check_level(exp)
print(exp)
print(result)
